package com.jruiz.nexo.calendar;
import android.content.Context;import android.content.SharedPreferences;
import org.json.JSONArray;import org.json.JSONObject;
import java.io.*;import java.net.HttpURLConnection;import java.net.URL;import java.nio.charset.StandardCharsets;import java.text.Normalizer;import java.time.LocalDate;import java.util.*;
/** Festivos Android alineados con Nexo Familia: mismo proveedor, ámbitos y fallback. */
public final class HolidayCalendarService{
 private HolidayCalendarService(){}
 private static final String PROVIDER="https://calendariosnacionales.com",MUNICIPALITY_INE="46202",MUNICIPALITY_NAME="Pobla de Vallbona, la",PROVINCE_NAME="Valencia/València",CCAA_CODE="ES-VC",REGION_SLUG="val",PROVINCE_SLUG="valencia",MUNICIPALITY_SLUG="pobla-de-vallbona-la";
 private static final long CACHE_MS=7L*24L*60L*60L*1000L;
 public static JSONObject load(Context c,int year){SharedPreferences p=c.getSharedPreferences("nexo_holidays",Context.MODE_PRIVATE);String k="holiday_"+MUNICIPALITY_INE+"_"+year,t=k+"_at",raw=p.getString(k,"");long at=p.getLong(t,0);if(!raw.isEmpty()&&System.currentTimeMillis()-at<CACHE_MS){JSONObject v=parse(raw);if(v!=null){put(v,"year",year);put(v,"cache","fresh");return v;}}try{JSONObject v=fetchYear(year);p.edit().putString(k,v.toString()).putLong(t,System.currentTimeMillis()).apply();return v;}catch(Exception e){if(!raw.isEmpty()){JSONObject v=parse(raw);if(v!=null){put(v,"year",year);put(v,"cache","stale");return v;}}return fallback(year);}}
 private static JSONObject fetchYear(int year)throws Exception{Map<String,JSONObject> m=new LinkedHashMap<>();addPermanent(m,year);int ok=0;String n=PROVIDER+"/es/v1/"+year+"/nacionales.json",r=PROVIDER+"/es/v1/"+year+"/regiones/"+REGION_SLUG+".json",l=PROVIDER+"/es/v1/"+year+"/localidades/"+REGION_SLUG+"/"+PROVINCE_SLUG+"/"+MUNICIPALITY_SLUG+".json";if(layer(n,m,new String[]{"national"}))ok++;if(layer(r,m,new String[]{"national","regional"}))ok++;if(layer(l,m,new String[]{"provincial","local"}))ok++;JSONObject o=new JSONObject();o.put("year",year);o.put("status",ok>=2?"ready":"partial");o.put("holidays",new JSONArray(m.values()));o.put("attribution","Festivos: CalendariosNacionales.com · fuentes oficiales indicadas por el proveedor");location(o);o.put("cache","network");return o;}
 private static boolean layer(String url,Map<String,JSONObject> m,String[] allowed)throws Exception{String raw=get(url);if(raw==null)return false;String low=norm(raw);if(low.contains("provisional")||low.contains("proyeccion")||low.contains("estimacion")||low.contains("pendiente de confirmar")||low.contains("pendiente de publicacion"))return false;Object root=raw.trim().startsWith("[")?new JSONArray(raw):new JSONObject(raw);collect(root,m,allowed,url);return true;}
 private static void collect(Object v,Map<String,JSONObject> m,String[] allowed,String url)throws Exception{if(v instanceof JSONArray){JSONArray a=(JSONArray)v;for(int i=0;i<a.length();i++)collect(a.opt(i),m,allowed,url);return;}if(!(v instanceof JSONObject))return;JSONObject o=(JSONObject)v;String d=o.optString("date",""),name=o.optString("name",""),s=scope(o.optString("scope",""));if(d.matches("\\d{4}-\\d{2}-\\d{2}")&&!name.trim().isEmpty()&&s!=null&&has(allowed,s)){JSONObject src=new JSONObject();src.put("ref",o.optString("source","CalendariosNacionales.com"));src.put("url",o.optString("sourceUrl",url));JSONObject h=new JSONObject();h.put("date",d);h.put("name",name.trim());h.put("level",s);h.put("source",src);h.put("sourceKind","provider");m.put(d+"|"+norm(name),h);return;}JSONArray names=o.names();if(names!=null)for(int i=0;i<names.length();i++)collect(o.opt(names.optString(i)),m,allowed,url);}
 private static String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setRequestMethod("GET");c.setConnectTimeout(10000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");int code=c.getResponseCode();if(code==404){c.disconnect();return null;}if(code<200||code>=300){c.disconnect();throw new IOException("HTTP "+code);}StringBuilder b=new StringBuilder();try(InputStream in=c.getInputStream();BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String x;while((x=r.readLine())!=null)b.append(x);}c.disconnect();return b.toString();}
 private static JSONObject fallback(int y){Map<String,JSONObject> m=new LinkedHashMap<>();try{addPermanent(m,y);}catch(Exception ignored){}JSONObject o=new JSONObject();put(o,"year",y);put(o,"status","partial");put(o,"holidays",new JSONArray(m.values()));put(o,"attribution","Festivos nacionales permanentes · BOE");location(o);put(o,"cache","fallback");return o;}
 private static void addPermanent(Map<String,JSONObject> m,int y)throws Exception{add(m,LocalDate.of(y,1,1),"Año Nuevo");add(m,LocalDate.of(y,5,1),"Fiesta del Trabajo");add(m,LocalDate.of(y,8,15),"Asunción de la Virgen");add(m,LocalDate.of(y,10,12),"Fiesta Nacional de España");add(m,LocalDate.of(y,11,1),"Todos los Santos");add(m,LocalDate.of(y,12,6),"Día de la Constitución Española");add(m,LocalDate.of(y,12,8),"Inmaculada Concepción");add(m,LocalDate.of(y,12,25),"Natividad del Señor");add(m,easter(y).minusDays(2),"Viernes Santo");}
 private static void add(Map<String,JSONObject> m,LocalDate d,String n)throws Exception{JSONObject s=new JSONObject();s.put("ref","BOE · RD 2001/1983 art. 45");s.put("url","https://www.boe.es/buscar/act.php?id=BOE-A-1983-20906");JSONObject h=new JSONObject();h.put("date",d.toString());h.put("name",n);h.put("level","national");h.put("source",s);h.put("sourceKind","permanent");m.put(d+"|"+norm(n),h);}
 private static void location(JSONObject o){put(o,"municipalityIne",MUNICIPALITY_INE);put(o,"municipalityName",MUNICIPALITY_NAME);put(o,"provinceName",PROVINCE_NAME);put(o,"ccaaCode",CCAA_CODE);}
 private static String scope(String s){String n=norm(s);if(n.equals("nacional")||n.equals("national"))return"national";if(n.equals("autonomico")||n.equals("regional"))return"regional";if(n.equals("provincial"))return"provincial";if(n.equals("local"))return"local";return null;}
 private static boolean has(String[] a,String x){for(String s:a)if(s.equals(x))return true;return false;}private static String norm(String s){return Normalizer.normalize(s==null?"":s,Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).trim();}private static JSONObject parse(String s){try{return new JSONObject(s);}catch(Exception e){return null;}}private static void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(Exception ignored){}}
 private static LocalDate easter(int y){int a=y%19,b=y/100,c=y%100,d=b/4,e=b%4,f=(b+8)/25,g=(b-f+1)/3,h=(19*a+b-d-g+15)%30,i=c/4,k=c%4,l=(32+2*e+2*i-h-k)%7,m=(a+11*h+22*l)/451,mo=(h+l-7*m+114)/31,da=((h+l-7*m+114)%31)+1;return LocalDate.of(y,mo,da);}
}
